(()=>{const usd=v=>Number.isFinite(Number(v))&&String(v).trim()!==''?'$'+(Number(v)/6.6753).toFixed(2)+' USD':'Price unavailable';
const positions={"shoes":[0,0],"hoodies":[25,0],"jackets":[50,0],"pants":[75,0],"hats":[100,0],"socks":[0,50],"electronics":[25,50],"watches":[50,50],"belts":[75,50],"slippers":[100,50],"t-shirts":[0,100],"sets":[25,100],"jersey":[50,100],"accessories":[75,100],"other":[100,100]};const art=k=>`<span class="category-art" style="--cx:${positions[k][0]}%;--cy:${positions[k][1]}%" aria-hidden="true"></span>`;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const buy=p=>'https://joyagoo.com/product?id='+encodeURIComponent(p.weidianId)+'&platform=WEIDIAN&productUrl=&productPwd=';const defs=[['shoes','Shoes','shoes'],['hoodies','Hoodies','hoodies-sweaters'],['jackets','Jackets','jackets'],['pants','Pants','pants-shorts'],['hats','Headwear','headwear'],['t-shirts','T-Shirts','t-shirts'],['accessories','Accessories','accessories'],['sets','Short Sets','ShortSets'],['jersey','Jersey','jersey'],['electronics','Electronics','electronics'],['socks','Socks',null],['watches','Watches',null],['belts','Belts',null],['slippers','Slippers',null],['other','Other Finds','other-stuff']];const match=(p,k,c)=>c?p.category===c:({socks:/\bsocks?\b/i,watches:/\bwatch(?:es)?\b/i,belts:/\bbelts?\b/i,slippers:/\b(slippers?|slides?|sandals?)\b/i}[k]).test(p.name);fetch('/catalog.json').then(r=>r.json()).then(d=>{const all=d.products.filter(p=>/^\d+$/.test(String(p.weidianId||''))&&p.image);const pick=(cat)=>all.find(p=>p.category===cat && (cat!=='shoes'||p.category==='shoes') && (cat!=='jackets'||p.id!=='8727'));document.querySelector('#category-grid').innerHTML=defs.map(([slug,label,cat])=>{const p=slug==='shoes'?pick('shoes'):slug==='jackets'?all.filter(p=>p.category==='jackets')[1]:all.find(p=>match(p,slug,cat));return `<a class="category-card" href="/categories/${slug}/">${art(slug)}<div class="category-caption">${esc(label)} <span>↗</span></div></a>`}).join('');}).catch(()=>{document.querySelector('#category-grid').textContent='Unable to load categories.'})})();
